def norm(value):
	key = str(value or "").strip().lower()
	if key in ["you", "me", "personal", "people", "for you"]:
		return "personal"
	if key in ["business", "company", "companies", "for your business"]:
		return "business"
	return "both"


def tag_of(aud):
	if aud == "personal":
		return "For you"
	if aud == "business":
		return "For your business"
	return ""


def read_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [line for line in raw.split("\n") if line.strip()]
	if not isinstance(raw, list):
		return []
	return [str(line) for line in raw if str(line).strip()]


def split_row(line, size):
	parts = [part.strip() for part in str(line).split("|")]
	while len(parts) < size:
		parts.append("")
	return parts

rows = []
try:
	for line in read_rows(props.get("people")):
		parts = split_row(line, 4)
		if not parts[0]:
			continue
		digits = "".join([ch for ch in parts[2] if ch.isdigit()])
		if digits.startswith("0"):
			digits = "+44" + digits[1:]
		rows.append({"name": parts[0], "does": parts[1], "phone": parts[2], "tel": ("tel:" + digits) if digits else "", "aud": norm(parts[3])})
except Exception:
	rows = []
component.rows = rows
